package app.snaptocart.scan;
import org.springframework.http.MediaType; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.io.IOException; import java.util.*;
@RestController @RequestMapping("/api/scans") public class ScanController { private final ScanService service; public ScanController(ScanService s){service=s;} @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) ScanService.ScanResponse scan(Authentication a,@RequestPart("image") MultipartFile f)throws IOException{String t=Optional.ofNullable(f.getContentType()).orElse("");if(!Set.of("image/jpeg","image/png","image/webp").contains(t))throw new IllegalArgumentException("Unsupported image type");return service.create((UUID)a.getPrincipal(),f.getBytes(),t);} @GetMapping List<ScanService.HistoryItem> history(Authentication a){return service.history((UUID)a.getPrincipal());} }
